    public Object calculateFee(String symbol, Object type, Object side, Object amount, Object price, Object takerOrMaker, Map<String, Object> parameters)
    {
        /**
         * @method
         * @description calculates the presumptive fee that would be charged for an order
         * @param {string} symbol unified market symbol
         * @param {string} type not used by btcmarkets.calculateFee
         * @param {string} side not used by btcmarkets.calculateFee
         * @param {float} amount how much you want to trade, in units of the base currency on most exchanges, or number of contracts
         * @param {float} price the price for the order to be filled at, in units of the quote currency
         * @param {string} takerOrMaker 'taker' or 'maker'
         * @param {object} params
         * @returns {object} contains the rate, the percentage multiplied to the order amount to obtain the fee amount, and cost, the total value of the fee in units of the quote currency, for the order
         */
        Map<String, Object> market = (Map<String, Object>) this.market(symbol);
        String currency = null;
        String cost = null;
        if (java.util.Objects.equals(((Map<String, Object>)market).get("quote"), "AUD"))
        {
            currency = this.safeString(market, "quote");
            String amountString = this.numberToString(amount);
            String priceString = this.numberToString(price);
            String otherUnitsAmount = Precise.stringMul(amountString, priceString);
            cost = this.costToPrecision(symbol, otherUnitsAmount);
        } else
        {
            currency = this.safeString(market, "base");
            cost = this.amountToPrecision(symbol, amount);
        }
        Object rate = this.safeValue(market, java.util.Objects.requireNonNullElse(takerOrMaker, "taker"));
        String rateCost = Precise.stringMul(this.numberToString(rate), cost);
        String feeCost = this.feeToPrecision((String) (symbol), rateCost);
        if (java.util.Objects.equals(feeCost, null))
        {
            feeCost = "0";
        }
        return Helpers.newMap(
            "type", java.util.Objects.requireNonNullElse(takerOrMaker, "taker"),
            "currency", currency,
            "rate", rate,
            "cost", Helpers.parseFloat(feeCost)
        );
    }

    public String parseOrderStatus(String status)
    {
        Map<String, Object> statuses = new HashMap<String, Object>() {{
            put( "Accepted", "open" );
            put( "Placed", "open" );
            put( "Partially Matched", "open" );
            put( "Fully Matched", "closed" );
            put( "Cancelled", "canceled" );
            put( "Partially Cancelled", "canceled" );
            put( "Failed", "rejected" );
        }};
        return this.safeString(statuses, status, status);
    }

    public Object parseOrder(Object order, Map<String, Object> market)
    {
        //
        // createOrder
        //
        //     {
        //         "orderId": "7524",
        //         "marketId": "BTC-AUD",
        //         "side": "Bid",
        //         "type": "Limit",
        //         "creationTime": "2019-08-30T11:08:21.956000Z",
        //         "price": "100.12",
        //         "amount": "1.034",
        //         "openAmount": "1.034",
        //         "status": "Accepted",
        //         "clientOrderId": "1234-5678",
        //         "timeInForce": "IOC",
        //         "postOnly": false,
        //         "selfTrade": "P",
        //         "triggerAmount": "105",
        //         "targetAmount": "1000"
        //     }
        //
        Long timestamp = this.parse8601(this.safeString(order, "creationTime"));
        String marketId = this.safeString(order, "marketId");
        Map<String, Object> marketResolved = (Map<String, Object>) this.safeMarket(marketId, market, "-", (String) null);
        String side = this.safeString(order, "side");
        if (java.util.Objects.equals(side, "Bid"))
        {
            side = "buy";
        } else if (java.util.Objects.equals(side, "Ask"))
        {
            side = "sell";
        }
        String type = this.safeStringLower(order, "type");
        String price = this.safeString(order, "price");
        String amount = this.safeString(order, "amount");
        String remaining = this.safeString(order, "openAmount");
        String status = this.parseOrderStatus(this.safeString(order, "status"));
        String id = this.safeString(order, "orderId");
        String clientOrderId = this.safeString(order, "clientOrderId");
        String timeInForce = this.safeString(order, "timeInForce");
        Boolean postOnly = (Boolean) this.safeBool(order, "postOnly", (Object) null);
        return this.safeOrder(Helpers.newMap(
            "info", order,
            "id", id,
            "clientOrderId", clientOrderId,
            "timestamp", timestamp,
            "datetime", this.iso8601(timestamp),
            "lastTradeTimestamp", null,
            "symbol", ((Map<String, Object>)marketResolved).get("symbol"),
            "type", type,
            "timeInForce", timeInForce,
            "postOnly", postOnly,
            "side", side,
            "price", price,
            "triggerPrice", this.safeNumber(order, "triggerPrice", (Object) null),
            "cost", null,
            "amount", amount,
            "filled", null,
            "remaining", remaining,
            "average", null,
            "status", status,
            "trades", null,
            "fee", null
        ), Helpers.toMapArg(marketResolved));
    }

